{
  int value;

  if (pin < GPIO1_PIN_NUM)
      value = HAL_GPIO_ReadPin((GPIO_TypeDef *)hwp_gpio1, pin);
  else if (pin < (GPIO1_PIN_NUM + GPIO2_PIN_NUM))
      value = HAL_GPIO_ReadPin((GPIO_TypeDef *)hwp_gpio2, pin - GPIO1_PIN_NUM);
